private static string? JsonStringValue(string json, string property) {
    Match match = Regex.Match(json, "\"" + Regex.Escape(property) + "\"\\s*:\\s*\"(?<v>[^\"]+)\"", RegexOptions.CultureInvariant);
    return match.Success ? match.Groups["v"].Value : null;
}

