        File.WriteAllText(stem + ".info.json", "{\"formats\":[{\"id\":\"WRONG_ID_01\",\"extractor_key\":\"WrongExtractor\"}],\"id\":\"" + correctId + "\",\"extractor_key\":\"Youtube\"}", Encoding.UTF8);

